const css = `
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;1,600&display=swap");

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: #fffdfb;
  color: #281b22;
  font-family: "DM Sans", sans-serif;
}

button,
input {
  font-family: inherit;
}

button {
  cursor: pointer;
}

a {
  text-decoration: none;
  color: inherit;
}

.app {
  min-height: 100vh;
  overflow: hidden;
}


/* TOP BAR */

.topbar {
  min-height: 35px;
  background: #281b22;
  color: white;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 12px;

  padding: 8px 20px;

  font-size: 10px;
}


/* HEADER */

.header {
  height: 82px;

  max-width: 1400px;

  margin: auto;

  padding: 0 5%;

  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo,
.footerLogo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logoCircle {
  width: 38px;
  height: 38px;

  border-radius: 50%;

  display: grid;
  place-items: center;

  background: #77364c;
  color: white;

  font-family: "Playfair Display", serif;
  font-style: italic;
  font-size: 22px;
}

.logo > div:last-child,
.footerLogo > div:last-child {
  display: flex;
  flex-direction: column;
}

.logo strong,
.footerLogo strong {
  font-size: 13px;
  letter-spacing: 3px;
}

.logo small,
.footerLogo small {
  margin-top: 4px;

  color: #85777e;

  font-size: 7px;
  letter-spacing: 1.5px;
}

nav {
  display: flex;
  gap: 30px;
}

nav a {
  font-size: 11px;
  font-weight: 600;
}

.headerActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logoutButton {
  border: 0;

  background: transparent;

  color: #777;

  font-size: 9px;
}

.cartButton {
  height: 42px;

  padding: 0 10px 0 15px;

  border: 0;
  border-radius: 30px;

  background: #281b22;
  color: white;

  display: flex;
  align-items: center;

  gap: 8px;
}

.cartButton span {
  font-size: 10px;
}

.cartButton b {
  width: 24px;
  height: 24px;

  border-radius: 50%;

  display: grid;
  place-items: center;

  background: white;
  color: #281b22;

  font-size: 9px;
}


/* HERO */

.hero {
  min-height: 650px;

  padding:
    70px
    max(5%, calc((100vw - 1300px) / 2));

  background:
    radial-gradient(
      circle at 78% 30%,
      #ead1c7,
      transparent 28%
    ),
    linear-gradient(
      120deg,
      #f9f4ef,
      #fffdfb 52%,
      #f1e2dc
    );

  display: grid;
  grid-template-columns: 0.9fr 1.1fr;

  align-items: center;

  gap: 60px;
}

.smallTitle {
  color: #91445c;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 2px;
}

.hero h1 {
  margin: 18px 0 22px;

  max-width: 620px;

  font-family: "Playfair Display", serif;

  font-size: clamp(
    50px,
    5vw,
    76px
  );

  line-height: 0.98;
}

.hero h1 em,
.about h2 em {
  color: #a44561;
}

.heroText > p {
  max-width: 500px;

  color: #756a70;

  font-size: 14px;

  line-height: 1.8;
}

.heroButtons {
  margin-top: 32px;

  display: flex;
  align-items: center;

  gap: 25px;
}

.primaryButton,
.whatsappButton {
  min-height: 51px;

  padding: 0 22px;

  border-radius: 30px;

  background: #77364c;
  color: white;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  font-size: 10px;
  font-weight: 700;
}

.secondaryButton {
  padding-bottom: 4px;

  border-bottom: 1px solid #281b22;

  font-size: 10px;
  font-weight: 700;
}

.heroInfos {
  margin-top: 45px;

  display: flex;

  flex-wrap: wrap;

  gap: 16px;
}

.heroInfos span {
  color: #766a70;

  font-size: 9px;
}


/* HERO IMAGES - TOUJOURS NORMALES */

.heroVisual {
  height: 540px;

  position: relative;
}

.heroCircleBackground {
  width: 390px;
  height: 390px;

  position: absolute;

  right: 50px;
  top: 45px;

  border-radius: 50%;

  background: #e8cfc5;
}

.heroMainImage {
  position: absolute;

  right: 7%;
  top: 0;

  width: 56%;
  height: 90%;

  object-fit: cover;

  border-radius:
    220px
    220px
    15px
    15px;

  box-shadow:
    0 30px 60px
    rgba(50, 20, 30, 0.15);

  /* PAS DE FLOU */
  filter: none;
}

.heroSmallImage {
  position: absolute;

  left: 7%;
  bottom: 0;

  width: 31%;
  height: 43%;

  object-fit: cover;

  border-radius:
    120px
    120px
    12px
    12px;

  border: 8px solid #fffdfb;

  /* PAS DE FLOU */
  filter: none;
}

.heroCard {
  position: absolute;

  right: 0;
  bottom: 35px;

  width: 180px;

  padding: 17px;

  border-radius: 13px;

  background:
    rgba(255, 255, 255, 0.95);

  display: flex;
  flex-direction: column;

  box-shadow:
    0 20px 40px
    rgba(40, 20, 30, 0.12);
}

.heroCard small {
  color: #a44561;

  font-size: 7px;
  font-weight: 700;
}

.heroCard strong {
  margin: 7px 0 4px;

  font-family: "Playfair Display", serif;

  font-size: 19px;
}

.heroCard span {
  color: #776b70;

  font-size: 9px;
}


/* SERVICES */

.services {
  max-width: 1200px;

  margin: -28px auto 0;

  position: relative;
  z-index: 10;

  padding: 22px;

  border-radius: 14px;

  background: white;

  display: grid;
  grid-template-columns: repeat(3, 1fr);

  box-shadow:
    0 20px 50px
    rgba(40,20,30,0.1);
}

.services article {
  padding: 8px 25px;

  display: flex;
  align-items: center;

  gap: 15px;

  border-right:
    1px solid #eee2dc;
}

.services article:last-child {
  border-right: 0;
}

.services article > span {
  font-size: 22px;
}

.services article > div {
  display: flex;
  flex-direction: column;
}

.services strong {
  font-size: 10px;
}

.services small {
  margin-top: 4px;

  color: #81767b;

  font-size: 8px;
}


/* COLLECTION */

.collection {
  max-width: 1300px;

  margin: auto;

  padding: 110px 30px;
}

.collectionHeader {
  display: flex;

  align-items: end;
  justify-content: space-between;

  gap: 30px;
}

.collection h2,
.about h2 {
  margin: 7px 0 0;

  font-family: "Playfair Display", serif;

  font-size: 49px;
}

.searchBox {
  width: 250px;
  height: 45px;

  border:
    1px solid #e8ded9;

  border-radius: 30px;

  padding: 0 14px;

  display: flex;
  align-items: center;

  gap: 9px;
}

.searchBox input {
  width: 100%;

  border: 0;
  outline: 0;

  background: transparent;

  font-size: 10px;
}

.categories {
  margin: 32px 0;

  display: flex;

  gap: 7px;

  overflow-x: auto;
}

.categories button {
  flex: 0 0 auto;

  padding: 10px 16px;

  border:
    1px solid #e7ddd8;

  border-radius: 30px;

  background: white;

  font-size: 9px;
  font-weight: 600;
}

.categories button.active {
  border-color: #281b22;

  background: #281b22;
  color: white;
}


/* PRODUCTS */

.products {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 35px 20px;
}

.productImage {
  height: 440px;

  position: relative;

  overflow: hidden;

  border-radius: 12px;

  background: #eadfd9;
}


/*
  IMPORTANT :
  SEULES LES IMAGES DANS .productImage
  PEUVENT ÊTRE FLOUTÉES
*/

.productPhoto {
  width: 100%;
  height: 100%;

  object-fit: cover;

  transition:
    filter 0.35s ease,
    transform 0.35s ease;
}


/* IMAGE FLOUTÉE */

.productPhoto.locked {
  filter: blur(18px);

  transform: scale(1.12);

  cursor: pointer;
}


/* IMAGE APRÈS CONNEXION */

.productPhoto.unlocked {
  filter: none;

  transform: scale(1);

  cursor: default;
}

.product:hover
.productPhoto.unlocked {
  transform: scale(1.03);
}


/* BOUTON VERROU */

.lockOverlay {
  position: absolute;

  z-index: 8;

  top: 50%;
  left: 50%;

  transform:
    translate(-50%, -50%);

  width: 145px;
  height: 105px;

  border: 0;
  border-radius: 15px;

  background:
    rgba(255,255,255,0.92);

  backdrop-filter: blur(12px);

  box-shadow:
    0 15px 40px
    rgba(0,0,0,0.16);

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;
}

.lockIcon {
  font-size: 22px;
}

.lockOverlay strong {
  margin-top: 6px;

  color: #281b22;

  font-size: 10px;
}

.lockOverlay small {
  margin-top: 3px;

  color: #84787e;

  font-size: 7px;
}

.categoryBadge {
  position: absolute;

  z-index: 10;

  top: 12px;
  left: 12px;

  padding: 7px 10px;

  border-radius: 20px;

  background: white;

  font-size: 7px;
  font-weight: 700;
}

.favoriteButton {
  position: absolute;

  z-index: 10;

  top: 12px;
  right: 12px;

  width: 37px;
  height: 37px;

  border: 0;
  border-radius: 50%;

  background: white;

  font-size: 19px;
}

.favoriteButton.liked {
  color: #a44561;
}

.addToCart {
  position: absolute;

  z-index: 10;

  left: 13px;
  right: 13px;
  bottom: 13px;

  height: 42px;

  border: 0;
  border-radius: 30px;

  background:
    rgba(40,27,34,0.94);

  color: white;

  font-size: 9px;
  font-weight: 700;

  opacity: 0;

  transform:
    translateY(8px);

  transition: 0.25s;
}

.product:hover .addToCart {
  opacity: 1;

  transform: none;
}

.productInfo {
  padding: 14px 4px;
}

.productInfo > small {
  color: #8a7d83;

  font-size: 7px;

  letter-spacing: 1px;
}

.productInfo h3 {
  margin: 4px 0 7px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 19px;
}

.price {
  display: flex;

  align-items: center;

  gap: 10px;
}

.price strong {
  color: #77364c;

  font-size: 12px;
}

.price del {
  color: #aaa0a4;

  font-size: 9px;
}

.sizes {
  margin-top: 11px;

  display: flex;

  gap: 5px;
}

.sizes span {
  width: 27px;
  height: 23px;

  border:
    1px solid #e4dad5;

  border-radius: 5px;

  display: grid;
  place-items: center;

  font-size: 7px;
}


/* ABOUT - JAMAIS FLOUTÉ */

.about {
  padding:
    100px
    max(6%, calc((100vw - 1200px) / 2));

  background: #f7f0eb;

  display: grid;
  grid-template-columns:
    1fr 1fr;

  gap: 80px;

  align-items: center;
}

.aboutImage {
  height: 560px;

  overflow: hidden;

  border-radius:
    240px
    240px
    15px
    15px;
}

.aboutImage img {
  width: 100%;
  height: 100%;

  object-fit: cover;

  /* PAS DE FLOU */
  filter: none;
}

.about h2 {
  font-size: 58px;
}

.aboutText > p {
  color: #756a6f;

  font-size: 13px;

  line-height: 1.8;
}

.about ul {
  padding: 0;

  margin: 28px 0;

  list-style: none;

  display: grid;

  gap: 11px;

  font-size: 11px;
}

.whatsappButton {
  background: #435c4e;
}


/* FOOTER */

footer {
  padding: 60px 20px 30px;

  background: #281b22;

  color: white;

  text-align: center;
}

.footerLogo {
  justify-content: center;
}

.footerLogo .logoCircle {
  background: #e5c8bc;

  color: #281b22;
}

footer p {
  margin: 20px;

  color: #b9afb4;

  font-size: 10px;
}

.socialLinks {
  margin-bottom: 35px;

  display: flex;

  justify-content: center;

  gap: 25px;
}

.socialLinks a {
  font-size: 9px;
}

footer > small {
  color: #82787d;

  font-size: 8px;
}


/* LOGIN MODAL */

.loginOverlay {
  position: fixed;

  inset: 0;

  z-index: 10000;

  padding: 20px;

  background:
    rgba(25,15,20,0.68);

  backdrop-filter: blur(8px);

  display: flex;

  align-items: center;
  justify-content: center;
}

.loginModal {
  width: min(
    430px,
    100%
  );

  max-height: 95vh;

  overflow-y: auto;

  position: relative;

  padding: 34px 30px 27px;

  border-radius: 22px;

  background: white;

  text-align: center;

  box-shadow:
    0 40px 100px
    rgba(0,0,0,0.3);

  animation:
    modalOpen
    0.22s ease;
}

@keyframes modalOpen {
  from {
    opacity: 0;

    transform:
      translateY(15px)
      scale(0.97);
  }

  to {
    opacity: 1;

    transform: none;
  }
}

.closeModal {
  position: absolute;

  right: 13px;
  top: 13px;

  width: 35px;
  height: 35px;

  border: 0;
  border-radius: 50%;

  background: #f4eeee;

  font-size: 20px;
}

.loginBrand {
  display: flex;

  flex-direction: column;

  align-items: center;
}

.loginLogo {
  width: 55px;
  height: 55px;

  margin-bottom: 10px;

  border-radius: 50%;

  background: #77364c;

  color: white;

  display: grid;
  place-items: center;

  font-family:
    "Playfair Display",
    serif;

  font-style: italic;

  font-size: 28px;
}

.loginBrand > strong {
  font-size: 12px;

  letter-spacing: 3px;
}

.loginBrand > small {
  margin-top: 4px;

  color: #988c91;

  font-size: 7px;

  letter-spacing: 1px;
}

.selectedProduct {
  margin: 20px 0;

  padding: 9px;

  border-radius: 11px;

  background: #f9f5f2;

  display: flex;

  align-items: center;

  gap: 11px;

  text-align: left;
}

.selectedProduct img {
  width: 48px;
  height: 58px;

  object-fit: cover;

  border-radius: 7px;

  filter: blur(5px);
}

.selectedProduct > div {
  display: flex;

  flex-direction: column;
}

.selectedProduct small {
  color: #9b8e94;

  font-size: 6px;
}

.selectedProduct strong {
  margin-top: 3px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 14px;
}

.loginModal h2 {
  max-width: 330px;

  margin:
    22px auto
    10px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 27px;

  line-height: 1.12;
}

.loginDescription {
  max-width: 330px;

  margin:
    0 auto
    23px;

  color: #7c7076;

  font-size: 10px;

  line-height: 1.7;
}

.facebookButton,
.googleButton,
.emailButton,
.continueButton {
  width: 100%;
  height: 49px;

  position: relative;

  border-radius: 10px;

  font-size: 10px;
  font-weight: 700;
}

.facebookButton {
  border: 0;

  background: #1877f2;

  color: white;
}

.facebookButton span {
  position: absolute;

  left: 18px;

  top: 50%;

  transform:
    translateY(-50%);

  font-family: Arial;

  font-size: 22px;

  font-weight: 900;
}

.googleButton {
  margin-top: 9px;

  border:
    1px solid #ddd5d1;

  background: white;
}

.googleButton span {
  position: absolute;

  left: 18px;

  top: 50%;

  transform:
    translateY(-50%);

  font-weight: 800;
}

.separator {
  margin: 18px 0;

  display: flex;

  align-items: center;

  gap: 10px;
}

.separator span {
  flex: 1;

  height: 1px;

  background: #e7ded9;
}

.separator small {
  color: #9b8f94;

  font-size: 7px;
}

.emailButton {
  border:
    1px solid #281b22;

  background: white;
}

.privacyText {
  max-width: 330px;

  margin:
    17px auto
    0;

  color: #9d9196;

  font-size: 7px;

  line-height: 1.6;
}

.emailForm {
  text-align: left;
}

.emailForm h2,
.emailForm p {
  text-align: center;
}

.emailForm p {
  color: #7c7076;

  font-size: 10px;
}

.emailForm label {
  display: block;

  margin-bottom: 7px;

  font-size: 8px;

  font-weight: 700;
}

.emailForm input {
  width: 100%;
  height: 48px;

  padding: 0 14px;

  border:
    1px solid #ded4cf;

  border-radius: 9px;

  outline: 0;
}

.emailForm input:focus {
  border-color: #77364c;
}

.backButton {
  padding: 0;

  border: 0;

  background: transparent;

  font-size: 9px;
}

.continueButton {
  margin-top: 11px;

  border: 0;

  background: #77364c;

  color: white;
}

.emailForm > small {
  display: block;

  margin-top: 12px;

  color: #9a8e93;

  font-size: 7px;

  text-align: center;
}


/* CART */

.cartOverlay {
  position: fixed;

  inset: 0;

  z-index: 9000;

  background:
    rgba(30,15,20,0.5);

  display: flex;

  justify-content: flex-end;
}

.cartDrawer {
  width: min(
    430px,
    100%
  );

  height: 100%;

  background: white;

  display: flex;

  flex-direction: column;
}

.cartHeader {
  padding: 20px;

  border-bottom:
    1px solid #eee4df;

  display: flex;

  align-items: center;

  justify-content: space-between;
}

.cartHeader h2 {
  margin: 0;

  font-family:
    "Playfair Display",
    serif;
}

.cartHeader small {
  color: #867a80;

  font-size: 8px;
}

.cartHeader button {
  border: 0;

  background: transparent;

  font-size: 22px;
}

.cartContent {
  flex: 1;

  overflow-y: auto;

  padding: 0 20px;
}

.emptyCart {
  margin-top: 100px;

  text-align: center;

  color: #81757b;
}

.emptyCart > span {
  font-size: 40px;
}

.emptyCart h3 {
  font-family:
    "Playfair Display",
    serif;
}

.emptyCart p {
  font-size: 10px;
}

.cartItem {
  padding: 18px 0;

  display: grid;

  grid-template-columns:
    90px 1fr;

  gap: 14px;

  border-bottom:
    1px solid #eee4df;
}

.cartItem img {
  width: 90px;
  height: 120px;

  object-fit: cover;

  border-radius: 8px;

  /* Dans le panier l'image est normale */
  filter: none;
}

.cartItem h4 {
  margin: 0 0 7px;

  font-family:
    "Playfair Display",
    serif;
}

.cartItem strong {
  color: #77364c;

  font-size: 10px;
}

.quantity {
  margin-top: 14px;

  display: flex;

  align-items: center;

  gap: 11px;
}

.quantity button {
  width: 27px;
  height: 27px;

  border:
    1px solid #e5dad6;

  border-radius: 50%;

  background: white;
}

.quantity span {
  font-size: 10px;

  font-weight: 700;
}

.removeButton {
  margin-top: 14px;

  padding: 0;

  border: 0;

  background: transparent;

  color: #9c5367;

  font-size: 8px;

  text-decoration: underline;
}

.cartFooter {
  padding: 20px;

  border-top:
    1px solid #eee4df;
}

.total {
  display: flex;

  justify-content: space-between;
}

.total strong {
  color: #77364c;
}

.checkoutButton {
  width: 100%;
  height: 50px;

  margin-top: 15px;

  border: 0;
  border-radius: 30px;

  background: #435c4e;

  color: white;

  font-size: 10px;
  font-weight: 700;
}


/* RESPONSIVE */

@media (max-width: 900px) {
  nav {
    display: none;
  }

  .hero {
    grid-template-columns: 1fr;
  }

  .heroText {
    text-align: center;
  }

  .heroText > p {
    margin-left: auto;
    margin-right: auto;
  }

  .heroButtons,
  .heroInfos {
    justify-content: center;
  }

  .heroVisual {
    width: min(600px, 100%);

    margin: auto;
  }

  .services {
    margin-left: 20px;

    margin-right: 20px;
  }

  .products {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .about {
    grid-template-columns: 1fr;
  }

  .aboutImage {
    width: min(
      600px,
      100%
    );

    margin: auto;
  }
}


@media (max-width: 600px) {
  .topbar {
    font-size: 8px;
  }

  .topbar span {
    display: none;
  }

  .header {
    height: 69px;

    padding: 0 15px;
  }

  .logo strong {
    font-size: 10px;
  }

  .logoutButton {
    display: none;
  }

  .cartButton {
    width: 42px;

    padding: 0;

    justify-content: center;

    position: relative;
  }

  .cartButton > span:nth-child(2) {
    display: none;
  }

  .cartButton b {
    position: absolute;

    top: -3px;
    right: -3px;

    width: 17px;
    height: 17px;

    background: #a44561;

    color: white;

    border:
      2px solid white;
  }

  .hero {
    padding:
      45px 18px
      70px;
  }

  .hero h1 {
    font-size: 47px;
  }

  .heroText > p {
    font-size: 12px;
  }

  .heroButtons {
    flex-direction: column;
  }

  .heroInfos {
    display: grid;
  }

  .heroVisual {
    height: 420px;
  }

  .heroCircleBackground {
    width: 290px;
    height: 290px;

    right: 0;
  }

  .heroMainImage {
    width: 69%;

    right: 2%;
  }

  .heroSmallImage {
    width: 35%;

    left: 0;
  }

  .heroCard {
    width: 145px;

    padding: 12px;
  }

  .services {
    grid-template-columns: 1fr;

    padding: 10px 18px;
  }

  .services article {
    padding: 15px 5px;

    border-right: 0;

    border-bottom:
      1px solid #eee2dc;
  }

  .collection {
    padding:
      80px 12px;
  }

  .collectionHeader {
    flex-direction: column;

    align-items: stretch;
  }

  .collection h2 {
    font-size: 37px;
  }

  .searchBox {
    width: 100%;
  }

  .products {
    gap: 25px 9px;
  }

  .productImage {
    height: 270px;
  }

  .lockOverlay {
    width: 115px;
    height: 87px;
  }

  .lockOverlay strong {
    font-size: 8px;
  }

  .lockOverlay small {
    font-size: 6px;
  }

  .addToCart {
    opacity: 1;

    transform: none;

    left: 8px;
    right: 8px;
    bottom: 8px;

    height: 36px;

    font-size: 7px;
  }

  .productInfo h3 {
    font-size: 15px;
  }

  .sizes {
    display: none;
  }

  .about {
    padding:
      75px 20px;
  }

  .aboutImage {
    height: 420px;
  }

