import React, { useMemo, useState } from "react";

const products = [
  {
    id: 1,
    name: "Robe Soa",
    category: "Nouveautés",
    price: 129000,
    oldPrice: 149000,
    image:
      "https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 2,
    name: "Robe Mialy",
    category: "Soirée",
    price: 159000,
    image:
      "https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 3,
    name: "Robe Vola",
    category: "Décontractée",
    price: 99000,
    image:
      "https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 4,
    name: "Robe Fara",
    category: "Cérémonie",
    price: 139000,
    image:
      "https://images.unsplash.com/photo-1529139574466-a303027c1d8b?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 5,
    name: "Robe Kanto",
    category: "Décontractée",
    price: 119000,
    image:
      "https://images.unsplash.com/photo-1539109136881-3be0616acf4b?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 6,
    name: "Robe Tahina",
    category: "Soirée",
    price: 179000,
    image:
      "https://images.unsplash.com/photo-1502716119720-b23a1e3ae1b5?auto=format&fit=crop&w=900&q=85",
  },
];

const categories = [
  "Toutes",
  "Nouveautés",
  "Soirée",
  "Cérémonie",
  "Décontractée",
];

const formatPrice = (price) =>
  new Intl.NumberFormat("fr-FR").format(price) + " Ar";

export default function App() {
  const [category, setCategory] = useState("Toutes");
  const [search, setSearch] = useState("");

  const [loggedIn, setLoggedIn] = useState(false);

  const [loginOpen, setLoginOpen] = useState(false);
  const [emailMode, setEmailMode] = useState(false);
  const [email, setEmail] = useState("");
  const [selectedProduct, setSelectedProduct] = useState(null);

  const [favorites, setFavorites] = useState([]);

  const [cart, setCart] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);

  const filteredProducts = useMemo(() => {
    return products.filter((product) => {
      const matchCategory =
        category === "Toutes" || product.category === category;

      const matchSearch = product.name
        .toLowerCase()
        .includes(search.toLowerCase());

      return matchCategory && matchSearch;
    });
  }, [category, search]);

  const cartCount = cart.reduce(
    (total, item) => total + item.quantity,
    0
  );

  const cartTotal = cart.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );

  const openLogin = (product = null) => {
    setSelectedProduct(product);
    setLoginOpen(true);
  };

  const closeLogin = () => {
    setLoginOpen(false);
    setSelectedProduct(null);
    setEmailMode(false);
  };

  const loginWithFacebook = () => {
    // À relier à ton backend OAuth officiel Facebook.
    // Exemple :
    window.location.href = "/auth/facebook";
  };

  const loginWithEmail = (e) => {
    e.preventDefault();

    if (!email.trim()) return;

    // Démo front-end uniquement.
    // À remplacer ensuite par ton vrai backend.
    setLoggedIn(true);
    setEmail("");
    closeLogin();
  };

  const logout = () => {
    setLoggedIn(false);
    setFavorites([]);
    setCart([]);
  };

  const toggleFavorite = (product) => {
    if (!loggedIn) {
      openLogin(product);
      return;
    }

    setFavorites((current) =>
      current.includes(product.id)
        ? current.filter((id) => id !== product.id)
        : [...current, product.id]
    );
  };

  const addToCart = (product) => {
    if (!loggedIn) {
      openLogin(product);
      return;
    }

    setCart((current) => {
      const exists = current.find((item) => item.id === product.id);

      if (exists) {
        return current.map((item) =>
          item.id === product.id
            ? {
                ...item,
                quantity: item.quantity + 1,
              }
            : item
        );
      }

      return [...current, { ...product, quantity: 1 }];
    });

    setCartOpen(true);
  };

  const changeQuantity = (id, amount) => {
    setCart((current) =>
      current
        .map((item) =>
          item.id === id
            ? {
                ...item,
                quantity: item.quantity + amount,
              }
            : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const removeFromCart = (id) => {
    setCart((current) =>
      current.filter((item) => item.id !== id)
    );
  };

  const orderWhatsApp = () => {
    const productsText = cart
      .map(
        (item) =>
          `${item.name} x${item.quantity} - ${formatPrice(
            item.price * item.quantity
          )}`
      )
      .join("\n");

    const message = `Bonjour Ravaka 👋

Je souhaite commander :

${productsText}

Total : ${formatPrice(cartTotal)}`;

    // Remplace avec ton vrai numéro.
    const whatsappNumber = "261340000000";

    window.open(
      `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(
        message
      )}`,
      "_blank"
    );
  };

  return (
    <>
      <style>{css}</style>

      <div className="app">
        {/* TOP BAR */}

        <div className="topbar">
          🇲🇬 Livraison partout à Madagascar
          <span>•</span>
          MVola • Orange Money • Airtel Money
        </div>

        {/* HEADER */}

        <header className="header">
          <a href="#home" className="logo">
            <div className="logoCircle">R</div>

            <div>
              <strong>RAVAKA</strong>
              <small>FEMME • MADAGASCAR</small>
            </div>
          </a>

          <nav>
            <a href="#collection">Nouveautés</a>
            <a href="#collection">Robes</a>
            <a href="#about">Notre univers</a>
            <a href="#delivery">Livraison</a>
          </nav>

          <div className="headerActions">
            {loggedIn && (
              <button
                className="logoutButton"
                onClick={logout}
              >
                Déconnexion
              </button>
            )}

            <button
              className="cartButton"
              onClick={() => setCartOpen(true)}
            >
              🛍️

              <span>Panier</span>

              <b>{cartCount}</b>
            </button>
          </div>
        </header>

        {/* HERO - PAS FLOUTÉ */}

        <section className="hero" id="home">
          <div className="heroText">
            <span className="smallTitle">
              ✦ COLLECTION FEMME 2026
            </span>

            <h1>
              Des robes pensées pour
              <em> vous faire rayonner.</em>
            </h1>

            <p>
              Découvrez une sélection de robes élégantes,
              modernes et féminines disponibles à Madagascar.
            </p>

            <div className="heroButtons">
              <a href="#collection" className="primaryButton">
                Découvrir la collection →
              </a>

              <a href="#about" className="secondaryButton">
                Notre univers
              </a>
            </div>

            <div className="heroInfos">
              <span>✓ Prix en Ariary</span>
              <span>✓ Livraison nationale</span>
              <span>✓ Commande WhatsApp</span>
            </div>
          </div>

          <div className="heroVisual">
            <div className="heroCircleBackground"></div>

            <img
              className="heroMainImage"
              src="https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=1000&q=90"
              alt="Collection Ravaka"
            />

            <img
              className="heroSmallImage"
              src="https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=600&q=90"
              alt="Robe Ravaka"
            />

            <div className="heroCard">
              <small>NOUVELLE PIÈCE</small>
              <strong>Robe Mialy</strong>
              <span>159 000 Ar</span>
            </div>
          </div>
        </section>

        {/* SERVICES */}

        <section className="services" id="delivery">
          <article>
            <span>🚚</span>

            <div>
              <strong>Livraison Madagascar</strong>
              <small>Antananarivo & provinces</small>
            </div>
          </article>

          <article>
            <span>📱</span>

            <div>
              <strong>Paiement mobile</strong>
              <small>MVola, Orange Money, Airtel Money</small>
            </div>
          </article>

          <article>
            <span>💬</span>

            <div>
              <strong>Commande WhatsApp</strong>
              <small>Rapide et simple</small>
            </div>
          </article>
        </section>

        {/* COLLECTION */}

        <section className="collection" id="collection">
          <div className="collectionHeader">
            <div>
              <span className="smallTitle">
                SÉLECTION RAVAKA
              </span>

              <h2>Les robes du moment</h2>
            </div>

            <div className="searchBox">
              🔎

              <input
                type="search"
                placeholder="Rechercher une robe..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>
          </div>

          {/* CATEGORIES */}

          <div className="categories">
            {categories.map((item) => (
              <button
                key={item}
                className={
                  category === item ? "active" : ""
                }
                onClick={() => setCategory(item)}
              >
                {item}
              </button>
            ))}
          </div>

          {/* LISTE DES PRODUITS */}

          <div className="products">
            {filteredProducts.map((product) => {
              const liked = favorites.includes(product.id);

              return (
                <article
                  className="product"
                  key={product.id}
                >
                  <div className="productImage">
                    {/* SEULE CETTE IMAGE EST FLOUTÉE */}

                    <img
                      src={product.image}
                      alt={product.name}
                      className={
                        loggedIn
                          ? "productPhoto unlocked"
                          : "productPhoto locked"
                      }
                      onClick={() => {
                        if (!loggedIn) {
                          openLogin(product);
                        }
                      }}
                    />

                    {!loggedIn && (
                      <button
                        className="lockOverlay"
                        onClick={() => openLogin(product)}
                      >
                        <span className="lockIcon">
                          🔒
                        </span>

                        <strong>
                          Voir la photo
                        </strong>

                        <small>
                          Connexion requise
                        </small>
                      </button>
                    )}

                    <span className="categoryBadge">
                      {product.category}
                    </span>

                    <button
                      className={`favoriteButton ${
                        liked ? "liked" : ""
                      }`}
                      onClick={() =>
                        toggleFavorite(product)
                      }
                    >
                      {liked ? "♥" : "♡"}
                    </button>

                    {loggedIn && (
                      <button
                        className="addToCart"
                        onClick={() =>
                          addToCart(product)
                        }
                      >
                        Ajouter au panier
                      </button>
                    )}
                  </div>

                  <div className="productInfo">
                    <small>{product.category}</small>

                    <h3>{product.name}</h3>

                    <div className="price">
                      <strong>
                        {formatPrice(product.price)}
                      </strong>

                      {product.oldPrice && (
                        <del>
                          {formatPrice(
                            product.oldPrice
                          )}
                        </del>
                      )}
                    </div>

                    <div className="sizes">
                      <span>S</span>
                      <span>M</span>
                      <span>L</span>
                      <span>XL</span>
                    </div>
                  </div>
                </article>
              );
            })}
          </div>
        </section>

        {/* ABOUT - PAS FLOUTÉ */}

        <section className="about" id="about">
          <div className="aboutImage">
            <img
              src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1100&q=85"
              alt="Boutique Ravaka"
            />
          </div>

          <div className="aboutText">
            <span className="smallTitle">
              NOTRE UNIVERS
            </span>

            <h2>
              Élégante.
              <br />
              Moderne.
              <br />
              <em>Malagasy.</em>
            </h2>

            <p>
              Ravaka propose une expérience shopping moderne
              pour découvrir et commander facilement des robes
              depuis Madagascar.
            </p>

            <ul>
              <li>✓ Prix en Ariary</li>
              <li>✓ Livraison nationale</li>
              <li>✓ Assistance WhatsApp</li>
              <li>✓ Paiement mobile</li>
            </ul>

            <a
              href="https://wa.me/261340000000"
              target="_blank"
              rel="noreferrer"
              className="whatsappButton"
            >
              💬 Contacter Ravaka
            </a>
          </div>
        </section>

        {/* FOOTER */}

        <footer>
          <div className="footerLogo">
            <div className="logoCircle">R</div>

            <div>
              <strong>RAVAKA</strong>
              <small>FEMME • MADAGASCAR</small>
            </div>
          </div>

          <p>
            Boutique de robes femme à Madagascar.
          </p>

          <div className="socialLinks">
            <a href="#">Instagram</a>
            <a href="#">Facebook</a>
            <a href="#">TikTok</a>
          </div>

          <small>
            © 2026 Ravaka Madagascar
          </small>
        </footer>

        {/* LOGIN MODAL */}

        {loginOpen && (
          <div
            className="loginOverlay"
            onClick={closeLogin}
          >
            <div
              className="loginModal"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                className="closeModal"
                onClick={closeLogin}
              >
                ×
              </button>

              <div className="loginBrand">
                <div className="loginLogo">
                  R
                </div>

                <strong>RAVAKA</strong>

                <small>
                  FEMME • MADAGASCAR
                </small>
              </div>

              {selectedProduct && (
                <div className="selectedProduct">
                  <img
                    src={selectedProduct.image}
                    alt={selectedProduct.name}
                  />

                  <div>
                    <small>
                      VOUS SOUHAITEZ VOIR
                    </small>

                    <strong>
                      {selectedProduct.name}
                    </strong>
                  </div>
                </div>
              )}

              {!emailMode ? (
                <>
                  <h2>
                    Connectez-vous pour voir la photo
                  </h2>

                  <p className="loginDescription">
                    Connectez-vous pour afficher les photos
                    de la collection, ajouter des favoris
                    et commander.
                  </p>

                  <button
                    className="facebookButton"
                    onClick={loginWithFacebook}
                  >
                    <span>f</span>

                    Continuer avec Facebook
                  </button>

                  <button
                    className="googleButton"
                    onClick={() => {
                      window.location.href =
                        "/auth/google";
                    }}
                  >
                    <span>G</span>

                    Continuer avec Google
                  </button>

                  <div className="separator">
                    <span></span>

                    <small>OU</small>

                    <span></span>
                  </div>

                  <button
                    className="emailButton"
                    onClick={() =>
                      setEmailMode(true)
                    }
                  >
                    Continuer avec mon e-mail
                  </button>

                  <p className="privacyText">
                    La connexion Facebook doit passer par
                    l'authentification OAuth officielle.
                    Votre site ne demande pas le mot de passe
                    Facebook.
                  </p>
                </>
              ) : (
                <form
                  className="emailForm"
                  onSubmit={loginWithEmail}
                >
                  <button
                    type="button"
                    className="backButton"
                    onClick={() =>
                      setEmailMode(false)
                    }
                  >
                    ← Retour
                  </button>

                  <h2>
                    Connexion
                  </h2>

                  <p>
                    Entrez votre adresse e-mail
                    pour continuer.
                  </p>

                  <label>
                    Adresse e-mail
                  </label>

                  <input
                    type="email"
                    placeholder="vous@email.com"
                    value={email}
                    onChange={(e) =>
                      setEmail(e.target.value)
                    }
                    required
                    autoFocus
                  />

                  <button
                    type="submit"
                    className="continueButton"
                  >
                    Continuer
                  </button>

                  <small>
                    Démonstration front-end :
                    à connecter ensuite à votre backend.
                  </small>
                </form>
              )}
            </div>
          </div>
        )}

        {/* CART */}

        {cartOpen && (
          <div
            className="cartOverlay"
            onClick={() => setCartOpen(false)}
          >
            <aside
              className="cartDrawer"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="cartHeader">
                <div>
                  <h2>Votre panier</h2>

                  <small>
                    {cartCount} article(s)
                  </small>
                </div>

                <button
                  onClick={() => setCartOpen(false)}
                >
                  ×
                </button>
              </div>

              <div className="cartContent">
                {cart.length === 0 ? (
                  <div className="emptyCart">
                    <span>🛍️</span>

                    <h3>
                      Votre panier est vide
                    </h3>

                    <p>
                      Ajoutez une robe pour commencer.
                    </p>
                  </div>
                ) : (
                  cart.map((item) => (
                    <div
                      className="cartItem"
                      key={item.id}
                    >
                      <img
                        src={item.image}
                        alt={item.name}
                      />

                      <div>
                        <h4>{item.name}</h4>

                        <strong>
                          {formatPrice(item.price)}
                        </strong>

                        <div className="quantity">
                          <button
                            onClick={() =>
                              changeQuantity(
                                item.id,
                                -1
                              )
                            }
                          >
                            −
                          </button>

                          <span>
                            {item.quantity}
                          </span>

                          <button
                            onClick={() =>
                              changeQuantity(
                                item.id,
                                1
                              )
                            }
                          >
                            +
                          </button>
                        </div>

                        <button
                          className="removeButton"
                          onClick={() =>
                            removeFromCart(
                              item.id
                            )
                          }
                        >
                          Supprimer
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>

              {cart.length > 0 && (
                <div className="cartFooter">
                  <div className="total">
                    <span>Total</span>

                    <strong>
                      {formatPrice(cartTotal)}
                    </strong>
                  </div>

                  <button
                    className="checkoutButton"
                    onClick={orderWhatsApp}
                  >
                    Commander sur WhatsApp →
                  </button>
                </div>
              )}
            </aside>
          </div>
        )}
      </div>
    </>
  );
}

const css = `
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,600;1,600&display=swap");

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: #fffdfb;
  color: #281b22;
  font-family: "DM Sans", sans-serif;
}

button,
input {
  font-family: inherit;
}

button {
  cursor: pointer;
}

a {
  text-decoration: none;
  color: inherit;
}

.app {
  min-height: 100vh;
  overflow: hidden;
}


/* TOP BAR */

.topbar {
  min-height: 35px;
  background: #281b22;
  color: white;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 12px;

  padding: 8px 20px;

  font-size: 10px;
}


/* HEADER */

.header {
  height: 82px;

  max-width: 1400px;

  margin: auto;

  padding: 0 5%;

  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo,
.footerLogo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logoCircle {
  width: 38px;
  height: 38px;

  border-radius: 50%;

  display: grid;
  place-items: center;

  background: #77364c;
  color: white;

  font-family: "Playfair Display", serif;
  font-style: italic;
  font-size: 22px;
}

.logo > div:last-child,
.footerLogo > div:last-child {
  display: flex;
  flex-direction: column;
}

.logo strong,
.footerLogo strong {
  font-size: 13px;
  letter-spacing: 3px;
}

.logo small,
.footerLogo small {
  margin-top: 4px;

  color: #85777e;

  font-size: 7px;
  letter-spacing: 1.5px;
}

nav {
  display: flex;
  gap: 30px;
}

nav a {
  font-size: 11px;
  font-weight: 600;
}

.headerActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logoutButton {
  border: 0;

  background: transparent;

  color: #777;

  font-size: 9px;
}

.cartButton {
  height: 42px;

  padding: 0 10px 0 15px;

  border: 0;
  border-radius: 30px;

  background: #281b22;
  color: white;

  display: flex;
  align-items: center;

  gap: 8px;
}

.cartButton span {
  font-size: 10px;
}

.cartButton b {
  width: 24px;
  height: 24px;

  border-radius: 50%;

  display: grid;
  place-items: center;

  background: white;
  color: #281b22;

  font-size: 9px;
}


/* HERO */

.hero {
  min-height: 650px;

  padding:
    70px
    max(5%, calc((100vw - 1300px) / 2));

  background:
    radial-gradient(
      circle at 78% 30%,
      #ead1c7,
      transparent 28%
    ),
    linear-gradient(
      120deg,
      #f9f4ef,
      #fffdfb 52%,
      #f1e2dc
    );

  display: grid;
  grid-template-columns: 0.9fr 1.1fr;

  align-items: center;

  gap: 60px;
}

.smallTitle {
  color: #91445c;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 2px;
}

.hero h1 {
  margin: 18px 0 22px;

  max-width: 620px;

  font-family: "Playfair Display", serif;

  font-size: clamp(
    50px,
    5vw,
    76px
  );

  line-height: 0.98;
}

.hero h1 em,
.about h2 em {
  color: #a44561;
}

.heroText > p {
  max-width: 500px;

  color: #756a70;

  font-size: 14px;

  line-height: 1.8;
}

.heroButtons {
  margin-top: 32px;

  display: flex;
  align-items: center;

  gap: 25px;
}

.primaryButton,
.whatsappButton {
  min-height: 51px;

  padding: 0 22px;

  border-radius: 30px;

  background: #77364c;
  color: white;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  font-size: 10px;
  font-weight: 700;
}

.secondaryButton {
  padding-bottom: 4px;

  border-bottom: 1px solid #281b22;

  font-size: 10px;
  font-weight: 700;
}

.heroInfos {
  margin-top: 45px;

  display: flex;

  flex-wrap: wrap;

  gap: 16px;
}

.heroInfos span {
  color: #766a70;

  font-size: 9px;
}


/* HERO IMAGES - TOUJOURS NORMALES */

.heroVisual {
  height: 540px;

  position: relative;
}

.heroCircleBackground {
  width: 390px;
  height: 390px;

  position: absolute;

  right: 50px;
  top: 45px;

  border-radius: 50%;

  background: #e8cfc5;
}

.heroMainImage {
  position: absolute;

  right: 7%;
  top: 0;

  width: 56%;
  height: 90%;

  object-fit: cover;

  border-radius:
    220px
    220px
    15px
    15px;

  box-shadow:
    0 30px 60px
    rgba(50, 20, 30, 0.15);

  /* PAS DE FLOU */
  filter: none;
}

.heroSmallImage {
  position: absolute;

  left: 7%;
  bottom: 0;

  width: 31%;
  height: 43%;

  object-fit: cover;

  border-radius:
    120px
    120px
    12px
    12px;

  border: 8px solid #fffdfb;

  /* PAS DE FLOU */
  filter: none;
}

.heroCard {
  position: absolute;

  right: 0;
  bottom: 35px;

  width: 180px;

  padding: 17px;

  border-radius: 13px;

  background:
    rgba(255, 255, 255, 0.95);

  display: flex;
  flex-direction: column;

  box-shadow:
    0 20px 40px
    rgba(40, 20, 30, 0.12);
}

.heroCard small {
  color: #a44561;

  font-size: 7px;
  font-weight: 700;
}

.heroCard strong {
  margin: 7px 0 4px;

  font-family: "Playfair Display", serif;

  font-size: 19px;
}

.heroCard span {
  color: #776b70;

  font-size: 9px;
}


/* SERVICES */

.services {
  max-width: 1200px;

  margin: -28px auto 0;

  position: relative;
  z-index: 10;

  padding: 22px;

  border-radius: 14px;

  background: white;

  display: grid;
  grid-template-columns: repeat(3, 1fr);

  box-shadow:
    0 20px 50px
    rgba(40,20,30,0.1);
}

.services article {
  padding: 8px 25px;

  display: flex;
  align-items: center;

  gap: 15px;

  border-right:
    1px solid #eee2dc;
}

.services article:last-child {
  border-right: 0;
}

.services article > span {
  font-size: 22px;
}

.services article > div {
  display: flex;
  flex-direction: column;
}

.services strong {
  font-size: 10px;
}

.services small {
  margin-top: 4px;

  color: #81767b;

  font-size: 8px;
}


/* COLLECTION */

.collection {
  max-width: 1300px;

  margin: auto;

  padding: 110px 30px;
}

.collectionHeader {
  display: flex;

  align-items: end;
  justify-content: space-between;

  gap: 30px;
}

.collection h2,
.about h2 {
  margin: 7px 0 0;

  font-family: "Playfair Display", serif;

  font-size: 49px;
}

.searchBox {
  width: 250px;
  height: 45px;

  border:
    1px solid #e8ded9;

  border-radius: 30px;

  padding: 0 14px;

  display: flex;
  align-items: center;

  gap: 9px;
}

.searchBox input {
  width: 100%;

  border: 0;
  outline: 0;

  background: transparent;

  font-size: 10px;
}

.categories {
  margin: 32px 0;

  display: flex;

  gap: 7px;

  overflow-x: auto;
}

.categories button {
  flex: 0 0 auto;

  padding: 10px 16px;

  border:
    1px solid #e7ddd8;

  border-radius: 30px;

  background: white;

  font-size: 9px;
  font-weight: 600;
}

.categories button.active {
  border-color: #281b22;

  background: #281b22;
  color: white;
}


/* PRODUCTS */

.products {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 35px 20px;
}

.productImage {
  height: 440px;

  position: relative;

  overflow: hidden;

  border-radius: 12px;

  background: #eadfd9;
}


/*
  IMPORTANT :
  SEULES LES IMAGES DANS .productImage
  PEUVENT ÊTRE FLOUTÉES
*/

.productPhoto {
  width: 100%;
  height: 100%;

  object-fit: cover;

  transition:
    filter 0.35s ease,
    transform 0.35s ease;
}


/* IMAGE FLOUTÉE */

.productPhoto.locked {
  filter: blur(18px);

  transform: scale(1.12);

  cursor: pointer;
}


/* IMAGE APRÈS CONNEXION */

.productPhoto.unlocked {
  filter: none;

  transform: scale(1);

  cursor: default;
}

.product:hover
.productPhoto.unlocked {
  transform: scale(1.03);
}


/* BOUTON VERROU */

.lockOverlay {
  position: absolute;

  z-index: 8;

  top: 50%;
  left: 50%;

  transform:
    translate(-50%, -50%);

  width: 145px;
  height: 105px;

  border: 0;
  border-radius: 15px;

  background:
    rgba(255,255,255,0.92);

  backdrop-filter: blur(12px);

  box-shadow:
    0 15px 40px
    rgba(0,0,0,0.16);

  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;
}

.lockIcon {
  font-size: 22px;
}

.lockOverlay strong {
  margin-top: 6px;

  color: #281b22;

  font-size: 10px;
}

.lockOverlay small {
  margin-top: 3px;

  color: #84787e;

  font-size: 7px;
}

.categoryBadge {
  position: absolute;

  z-index: 10;

  top: 12px;
  left: 12px;

  padding: 7px 10px;

  border-radius: 20px;

  background: white;

  font-size: 7px;
  font-weight: 700;
}

.favoriteButton {
  position: absolute;

  z-index: 10;

  top: 12px;
  right: 12px;

  width: 37px;
  height: 37px;

  border: 0;
  border-radius: 50%;

  background: white;

  font-size: 19px;
}

.favoriteButton.liked {
  color: #a44561;
}

.addToCart {
  position: absolute;

  z-index: 10;

  left: 13px;
  right: 13px;
  bottom: 13px;

  height: 42px;

  border: 0;
  border-radius: 30px;

  background:
    rgba(40,27,34,0.94);

  color: white;

  font-size: 9px;
  font-weight: 700;

  opacity: 0;

  transform:
    translateY(8px);

  transition: 0.25s;
}

.product:hover .addToCart {
  opacity: 1;

  transform: none;
}

.productInfo {
  padding: 14px 4px;
}

.productInfo > small {
  color: #8a7d83;

  font-size: 7px;

  letter-spacing: 1px;
}

.productInfo h3 {
  margin: 4px 0 7px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 19px;
}

.price {
  display: flex;

  align-items: center;

  gap: 10px;
}

.price strong {
  color: #77364c;

  font-size: 12px;
}

.price del {
  color: #aaa0a4;

  font-size: 9px;
}

.sizes {
  margin-top: 11px;

  display: flex;

  gap: 5px;
}

.sizes span {
  width: 27px;
  height: 23px;

  border:
    1px solid #e4dad5;

  border-radius: 5px;

  display: grid;
  place-items: center;

  font-size: 7px;
}


/* ABOUT - JAMAIS FLOUTÉ */

.about {
  padding:
    100px
    max(6%, calc((100vw - 1200px) / 2));

  background: #f7f0eb;

  display: grid;
  grid-template-columns:
    1fr 1fr;

  gap: 80px;

  align-items: center;
}

.aboutImage {
  height: 560px;

  overflow: hidden;

  border-radius:
    240px
    240px
    15px
    15px;
}

.aboutImage img {
  width: 100%;
  height: 100%;

  object-fit: cover;

  /* PAS DE FLOU */
  filter: none;
}

.about h2 {
  font-size: 58px;
}

.aboutText > p {
  color: #756a6f;

  font-size: 13px;

  line-height: 1.8;
}

.about ul {
  padding: 0;

  margin: 28px 0;

  list-style: none;

  display: grid;

  gap: 11px;

  font-size: 11px;
}

.whatsappButton {
  background: #435c4e;
}


/* FOOTER */

footer {
  padding: 60px 20px 30px;

  background: #281b22;

  color: white;

  text-align: center;
}

.footerLogo {
  justify-content: center;
}

.footerLogo .logoCircle {
  background: #e5c8bc;

  color: #281b22;
}

footer p {
  margin: 20px;

  color: #b9afb4;

  font-size: 10px;
}

.socialLinks {
  margin-bottom: 35px;

  display: flex;

  justify-content: center;

  gap: 25px;
}

.socialLinks a {
  font-size: 9px;
}

footer > small {
  color: #82787d;

  font-size: 8px;
}


/* LOGIN MODAL */

.loginOverlay {
  position: fixed;

  inset: 0;

  z-index: 10000;

  padding: 20px;

  background:
    rgba(25,15,20,0.68);

  backdrop-filter: blur(8px);

  display: flex;

  align-items: center;
  justify-content: center;
}

.loginModal {
  width: min(
    430px,
    100%
  );

  max-height: 95vh;

  overflow-y: auto;

  position: relative;

  padding: 34px 30px 27px;

  border-radius: 22px;

  background: white;

  text-align: center;

  box-shadow:
    0 40px 100px
    rgba(0,0,0,0.3);

  animation:
    modalOpen
    0.22s ease;
}

@keyframes modalOpen {
  from {
    opacity: 0;

    transform:
      translateY(15px)
      scale(0.97);
  }

  to {
    opacity: 1;

    transform: none;
  }
}

.closeModal {
  position: absolute;

  right: 13px;
  top: 13px;

  width: 35px;
  height: 35px;

  border: 0;
  border-radius: 50%;

  background: #f4eeee;

  font-size: 20px;
}

.loginBrand {
  display: flex;

  flex-direction: column;

  align-items: center;
}

.loginLogo {
  width: 55px;
  height: 55px;

  margin-bottom: 10px;

  border-radius: 50%;

  background: #77364c;

  color: white;

  display: grid;
  place-items: center;

  font-family:
    "Playfair Display",
    serif;

  font-style: italic;

  font-size: 28px;
}

.loginBrand > strong {
  font-size: 12px;

  letter-spacing: 3px;
}

.loginBrand > small {
  margin-top: 4px;

  color: #988c91;

  font-size: 7px;

  letter-spacing: 1px;
}

.selectedProduct {
  margin: 20px 0;

  padding: 9px;

  border-radius: 11px;

  background: #f9f5f2;

  display: flex;

  align-items: center;

  gap: 11px;

  text-align: left;
}

.selectedProduct img {
  width: 48px;
  height: 58px;

  object-fit: cover;

  border-radius: 7px;

  filter: blur(5px);
}

.selectedProduct > div {
  display: flex;

  flex-direction: column;
}

.selectedProduct small {
  color: #9b8e94;

  font-size: 6px;
}

.selectedProduct strong {
  margin-top: 3px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 14px;
}

.loginModal h2 {
  max-width: 330px;

  margin:
    22px auto
    10px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 27px;

  line-height: 1.12;
}

.loginDescription {
  max-width: 330px;

  margin:
    0 auto
    23px;

  color: #7c7076;

  font-size: 10px;

  line-height: 1.7;
}

.facebookButton,
.googleButton,
.emailButton,
.continueButton {
  width: 100%;
  height: 49px;

  position: relative;

  border-radius: 10px;

  font-size: 10px;
  font-weight: 700;
}

.facebookButton {
  border: 0;

  background: #1877f2;

  color: white;
}

.facebookButton span {
  position: absolute;

  left: 18px;

  top: 50%;

  transform:
    translateY(-50%);

  font-family: Arial;

  font-size: 22px;

  font-weight: 900;
}

.googleButton {
  margin-top: 9px;

  border:
    1px solid #ddd5d1;

  background: white;
}

.googleButton span {
  position: absolute;

  left: 18px;

  top: 50%;

  transform:
    translateY(-50%);

  font-weight: 800;
}

.separator {
  margin: 18px 0;

  display: flex;

  align-items: center;

  gap: 10px;
}

.separator span {
  flex: 1;

  height: 1px;

  background: #e7ded9;
}

.separator small {
  color: #9b8f94;

  font-size: 7px;
}

.emailButton {
  border:
    1px solid #281b22;

  background: white;
}

.privacyText {
  max-width: 330px;

  margin:
    17px auto
    0;

  color: #9d9196;

  font-size: 7px;

  line-height: 1.6;
}

.emailForm {
  text-align: left;
}

.emailForm h2,
.emailForm p {
  text-align: center;
}

.emailForm p {
  color: #7c7076;

  font-size: 10px;
}

.emailForm label {
  display: block;

  margin-bottom: 7px;

  font-size: 8px;

  font-weight: 700;
}

.emailForm input {
  width: 100%;
  height: 48px;

  padding: 0 14px;

  border:
    1px solid #ded4cf;

  border-radius: 9px;

  outline: 0;
}

.emailForm input:focus {
  border-color: #77364c;
}

.backButton {
  padding: 0;

  border: 0;

  background: transparent;

  font-size: 9px;
}

.continueButton {
  margin-top: 11px;

  border: 0;

  background: #77364c;

  color: white;
}

.emailForm > small {
  display: block;

  margin-top: 12px;

  color: #9a8e93;

  font-size: 7px;

  text-align: center;
}


/* CART */

.cartOverlay {
  position: fixed;

  inset: 0;

  z-index: 9000;

  background:
    rgba(30,15,20,0.5);

  display: flex;

  justify-content: flex-end;
}

.cartDrawer {
  width: min(
    430px,
    100%
  );

  height: 100%;

  background: white;

  display: flex;

  flex-direction: column;
}

.cartHeader {
  padding: 20px;

  border-bottom:
    1px solid #eee4df;

  display: flex;

  align-items: center;

  justify-content: space-between;
}

.cartHeader h2 {
  margin: 0;

  font-family:
    "Playfair Display",
    serif;
}

.cartHeader small {
  color: #867a80;

  font-size: 8px;
}

.cartHeader button {
  border: 0;

  background: transparent;

  font-size: 22px;
}

.cartContent {
  flex: 1;

  overflow-y: auto;

  padding: 0 20px;
}

.emptyCart {
  margin-top: 100px;

  text-align: center;

  color: #81757b;
}

.emptyCart > span {
  font-size: 40px;
}

.emptyCart h3 {
  font-family:
    "Playfair Display",
    serif;
}

.emptyCart p {
  font-size: 10px;
}

.cartItem {
  padding: 18px 0;

  display: grid;

  grid-template-columns:
    90px 1fr;

  gap: 14px;

  border-bottom:
    1px solid #eee4df;
}

.cartItem img {
  width: 90px;
  height: 120px;

  object-fit: cover;

  border-radius: 8px;

  /* Dans le panier l'image est normale */
  filter: none;
}

.cartItem h4 {
  margin: 0 0 7px;

  font-family:
    "Playfair Display",
    serif;
}

.cartItem strong {
  color: #77364c;

  font-size: 10px;
}

.quantity {
  margin-top: 14px;

  display: flex;

  align-items: center;

  gap: 11px;
}

.quantity button {
  width: 27px;
  height: 27px;

  border:
    1px solid #e5dad6;

  border-radius: 50%;

  background: white;
}

.quantity span {
  font-size: 10px;

  font-weight: 700;
}

.removeButton {
  margin-top: 14px;

  padding: 0;

  border: 0;

  background: transparent;

  color: #9c5367;

  font-size: 8px;

  text-decoration: underline;
}

.cartFooter {
  padding: 20px;

  border-top:
    1px solid #eee4df;
}

.total {
  display: flex;

  justify-content: space-between;
}

.total strong {
  color: #77364c;
}

.checkoutButton {
  width: 100%;
  height: 50px;

  margin-top: 15px;

  border: 0;
  border-radius: 30px;

  background: #435c4e;

  color: white;

  font-size: 10px;
  font-weight: 700;
}


/* RESPONSIVE */

@media (max-width: 900px) {
  nav {
    display: none;
  }

  .hero {
    grid-template-columns: 1fr;
  }

  .heroText {
    text-align: center;
  }

  .heroText > p {
    margin-left: auto;
    margin-right: auto;
  }

  .heroButtons,
  .heroInfos {
    justify-content: center;
  }

  .heroVisual {
    width: min(600px, 100%);

    margin: auto;
  }

  .services {
    margin-left: 20px;

    margin-right: 20px;
  }

  .products {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .about {
    grid-template-columns: 1fr;
  }

  .aboutImage {
    width: min(
      600px,
      100%
    );

    margin: auto;
  }
}


@media (max-width: 600px) {
  .topbar {
    font-size: 8px;
  }

  .topbar span {
    display: none;
  }

  .header {
    height: 69px;

    padding: 0 15px;
  }

  .logo strong {
    font-size: 10px;
  }

  .logoutButton {
    display: none;
  }

  .cartButton {
    width: 42px;

    padding: 0;

    justify-content: center;

    position: relative;
  }

  .cartButton > span:nth-child(2) {
    display: none;
  }

  .cartButton b {
    position: absolute;

    top: -3px;
    right: -3px;

    width: 17px;
    height: 17px;

    background: #a44561;

    color: white;

    border:
      2px solid white;
  }

  .hero {
    padding:
      45px 18px
      70px;
  }

  .hero h1 {
    font-size: 47px;
  }

  .heroText > p {
    font-size: 12px;
  }

  .heroButtons {
    flex-direction: column;
  }

  .heroInfos {
    display: grid;
  }

  .heroVisual {
    height: 420px;
  }

  .heroCircleBackground {
    width: 290px;
    height: 290px;

    right: 0;
  }

  .heroMainImage {
    width: 69%;

    right: 2%;
  }

  .heroSmallImage {
    width: 35%;

    left: 0;
  }

  .heroCard {
    width: 145px;

    padding: 12px;
  }

  .services {
    grid-template-columns: 1fr;

    padding: 10px 18px;
  }

  .services article {
    padding: 15px 5px;

    border-right: 0;

    border-bottom:
      1px solid #eee2dc;
  }

  .collection {
    padding:
      80px 12px;
  }

  .collectionHeader {
    flex-direction: column;

    align-items: stretch;
  }

  .collection h2 {
    font-size: 37px;
  }

  .searchBox {
    width: 100%;
  }

  .products {
    gap: 25px 9px;
  }

  .productImage {
    height: 270px;
  }

  .lockOverlay {
    width: 115px;
    height: 87px;
  }

  .lockOverlay strong {
    font-size: 8px;
  }

  .lockOverlay small {
    font-size: 6px;
  }

  .addToCart {
    opacity: 1;

    transform: none;

    left: 8px;
    right: 8px;
    bottom: 8px;

    height: 36px;

    font-size: 7px;
  }

  .productInfo h3 {
    font-size: 15px;
  }

  .sizes {
    display: none;
  }

  .about {
    padding:
      75px 20px;
  }

  .aboutImage {
    height: 420px;
  }

  .about h2 {
    font-size: 46px;
  }

  .loginModal {
    padding:
      32px 19px
      23px;

    border-radius: 18px;
  }

  .loginModal h2 {
    font-size: 24px;
  }
}
`;
